package id.unnes.bemfhunnes.auth;
import com.fasterxml.jackson.databind.ObjectMapper; import id.unnes.bemfhunnes.config.AppProperties; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.*;
public class TokenService { private final AppProperties props; private final ObjectMapper mapper=new ObjectMapper(); public TokenService(AppProperties p){props=p;} private String b64(byte[] b){return Base64.getUrlEncoder().withoutPadding().encodeToString(b);} private byte[] decode(String s){return Base64.getUrlDecoder().decode(s);} private String sign(String value)throws Exception{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(props.getJwtSecret().getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return b64(m.doFinal(value.getBytes(StandardCharsets.UTF_8)));} public String create(long id,String email,String role)throws Exception{Map<String,Object> p=Map.of("sub",id,"email",email,"role",role,"exp",Instant.now().plusSeconds(28800).getEpochSecond());String h=b64(mapper.writeValueAsBytes(Map.of("alg","HS256","typ","JWT")));String body=b64(mapper.writeValueAsBytes(p));return h+"."+body+"."+sign(h+"."+body);} public Map<String,Object> verify(String token){try{String[] x=token.split("\\.");if(x.length!=3||!MessageDigest.isEqual(sign(x[0]+"."+x[1]).getBytes(StandardCharsets.UTF_8),x[2].getBytes(StandardCharsets.UTF_8)))return null;Map<?,?> p=mapper.readValue(decode(x[1]),Map.class);if(((Number)p.get("exp")).longValue()<Instant.now().getEpochSecond())return null;return (Map<String,Object>)p;}catch(Exception e){return null;}}}
